import{_ as i}from"./chunks/ai-pipeline-08-governance-and-controls.C7M9duik.js";import{_ as t,o as r,c as a,a0 as s}from"./chunks/framework.DScjKhBS.js";const g=JSON.parse('{"title":"AI-assisted review without blind trust","description":"How to use AI as first-pass review support while preserving human accountability and security posture.","frontmatter":{"title":"AI-assisted review without blind trust","description":"How to use AI as first-pass review support while preserving human accountability and security posture."},"headers":[],"relativePath":"reports/pr-review-continuity/05-ai-assisted-review-without-blind-trust.md","filePath":"reports/pr-review-continuity/05-ai-assisted-review-without-blind-trust.md"}'),o={name:"reports/pr-review-continuity/05-ai-assisted-review-without-blind-trust.md"};function n(l,e,c,d,u,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<figure class="report-section-image-wrapper" aria-labelledby="fig-pr-ai-guardrails-caption"><img src="'+i+'" alt="Guardrailed AI workflow with a controlled gate and checklist" loading="lazy" class="report-section-image"><figcaption id="fig-pr-ai-guardrails-caption">AI guardrails: assistance inside policy boundaries, with human authority at merge</figcaption></figure><h1 id="ai-assisted-review-without-blind-trust" tabindex="-1">AI-assisted review without blind trust <a class="header-anchor" href="#ai-assisted-review-without-blind-trust" aria-label="Permalink to &quot;AI-assisted review without blind trust&quot;">​</a></h1><h2 id="recommended-ai-role-in-constrained-periods" tabindex="-1">Recommended AI role in constrained periods <a class="header-anchor" href="#recommended-ai-role-in-constrained-periods" aria-label="Permalink to &quot;Recommended AI role in constrained periods&quot;">​</a></h2><p>Use AI for:</p><ul><li>Diff summarization</li><li>Obvious risk flagging (security smells, deprecated APIs, missing tests/docs)</li><li>Reviewer attention routing (&quot;focus here first&quot;)</li></ul><p>Do <strong>not</strong> use AI for:</p><ul><li>Autonomous approval</li><li>Autonomous merge</li><li>Final security sign-off</li></ul><p>This matches existing project guardrails: AI can accelerate first pass, but merge remains human-gated.</p><hr><h2 id="human-review-protocol-for-ai-generated-or-ai-heavy-prs" tabindex="-1">Human-review protocol for AI-generated or AI-heavy PRs <a class="header-anchor" href="#human-review-protocol-for-ai-generated-or-ai-heavy-prs" aria-label="Permalink to &quot;Human-review protocol for AI-generated or AI-heavy PRs&quot;">​</a></h2><p>Require explicit checks on:</p><ol><li><strong>Correctness beyond happy path</strong> (edge cases, error handling)</li><li><strong>Security boundaries</strong> (auth, input validation, output encoding, secret handling)</li><li><strong>Operational behavior</strong> (timeouts, retries, logging, observability impact)</li><li><strong>Maintainability</strong> (duplication, naming clarity, change locality)</li></ol><p>If reviewer cannot explain a critical section, request decomposition or rewrite before approval.</p><hr><h2 id="cognitive-risk-controls" tabindex="-1">Cognitive risk controls <a class="header-anchor" href="#cognitive-risk-controls" aria-label="Permalink to &quot;Cognitive risk controls&quot;">​</a></h2><p>Recent research on agentic coding assistants indicates cognitive engagement can decline as sessions progress, with developers over-focusing on output success. Operationally, this implies:</p><ul><li>Add deliberate &quot;pause-and-verify&quot; checkpoints before approval</li><li>Require reviewer notes for high-risk decisions (not just LGTM)</li><li>Prefer staged reviews over one long review session</li><li>Use prompts/checklists that force edge-case and failure-mode thinking</li></ul><hr><h2 id="security-and-governance-minimums" tabindex="-1">Security and governance minimums <a class="header-anchor" href="#security-and-governance-minimums" aria-label="Permalink to &quot;Security and governance minimums&quot;">​</a></h2><p>Adopt baseline controls aligned with secure SDLC guidance:</p><ul><li>Secure coding standards + code review policy</li><li>Automated static/security checks in CI</li><li>Explicit risk-based review depth by change type</li><li>Documented lessons learned and recurring defect classes</li></ul><p>These controls remain mandatory even when staffing is constrained.</p><hr><h2 id="practical-policy-statement" tabindex="-1">Practical policy statement <a class="header-anchor" href="#practical-policy-statement" aria-label="Permalink to &quot;Practical policy statement&quot;">​</a></h2><p><code>AI comments are advisory evidence, not approval evidence.</code></p><p>Approval evidence must be human-understandable reasoning plus deterministic test/security results.</p><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/06-30-60-90-rollout.html">30-60-90 day rollout</a></p>',28)])])}const v=t(o,[["render",n]]);export{g as __pageData,v as default};
